/**
 * Builds the example models shown in the dashboard: downloads CC0 models from Poly Haven, packs each one into a GLB
 * standing on the floor, and renders the same camera shot twice (surface and violet mesh).
 *
 *   npx tsx --conditions=react-server scripts/build-examples.ts <cache-dir>
 *
 * Output: public/demo/<id>.glb, public/demo/posters/<id>.webp and <id>-mesh.webp, src/content/examples-data.json.
 * Examples are never presented as results generated by OrbitShelf. Real results live in src/config/showcase.ts.
 */
import { createHash } from "node:crypto";
import { createReadStream, existsSync } from "node:fs";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import path from "node:path";
import { NodeIO } from "@gltf-transform/core";
import { KHRONOS_EXTENSIONS } from "@gltf-transform/extensions";
import { center, dedup, prune } from "@gltf-transform/functions";
import { chromium } from "@playwright/test";
import sharp from "sharp";
import { diagnoseGlb } from "../src/lib/glb-tools";

/** Our id → Poly Haven id. */
const SOURCES: Record<string, string> = {
  modern_arm_chair_01: "modern_arm_chair_01",
  mid_century_lounge_chair: "mid_century_lounge_chair",
  brass_vase_03: "brass_vase_03",
  modern_ceiling_lamp_01: "modern_ceiling_lamp_01",
  alarm_clock_01: "alarm_clock_01",
  barrel_01: "Barrel_01",
  wooden_crate_01: "wooden_crate_01",
  lantern_01: "Lantern_01",
  camera_01: "Camera_01",
  marble_bust_01: "marble_bust_01",
  horse_statue_01: "horse_statue_01",
  concrete_cat_statue: "concrete_cat_statue",
};
/** Already in the repository: they only need posters. */
const LOCAL = ["vase", "lamp", "chair"];

const USER_AGENT = "OrbitShelf-build-examples/1.0";
const MAX_GLB_BYTES = 3.5 * 1024 * 1024;
const POSTER_PX = 640;
const ORBIT = "32deg 74deg 105%";

const root = process.cwd();
const demoDir = path.join(root, "public", "demo");
const posterDir = path.join(demoDir, "posters");

type FileEntry = { url: string; size: number; md5: string };
type GltfFiles = { gltf: { "1k": { gltf: FileEntry & { include?: Record<string, FileEntry> } } } };

async function download(entry: FileEntry, target: string) {
  if (existsSync(target) && createHash("md5").update(await readFile(target)).digest("hex") === entry.md5) return;
  const res = await fetch(entry.url, { headers: { "User-Agent": USER_AGENT } });
  if (!res.ok) throw new Error(`${entry.url}: HTTP ${res.status}`);
  const data = Buffer.from(await res.arrayBuffer());
  const md5 = createHash("md5").update(data).digest("hex");
  if (md5 !== entry.md5) throw new Error(`${entry.url}: checksum mismatch`);
  await mkdir(path.dirname(target), { recursive: true });
  await writeFile(target, data);
}

async function fetchSource(polyId: string, cache: string): Promise<string> {
  const res = await fetch(`https://api.polyhaven.com/files/${polyId}`, { headers: { "User-Agent": USER_AGENT } });
  if (!res.ok) throw new Error(`${polyId}: HTTP ${res.status}`);
  const gltf = ((await res.json()) as GltfFiles).gltf["1k"].gltf;
  const dir = path.join(cache, polyId);
  const main = path.join(dir, path.basename(new URL(gltf.url).pathname));
  await download(gltf, main);
  for (const [rel, entry] of Object.entries(gltf.include ?? {})) {
    const target = path.resolve(dir, rel);
    if (!target.startsWith(path.resolve(dir) + path.sep)) throw new Error(`${polyId}: unsafe path ${rel}`);
    await download(entry, target);
  }
  return main;
}

async function pack(source: string, id: string): Promise<void> {
  const io = new NodeIO().registerExtensions(KHRONOS_EXTENSIONS);
  const doc = await io.read(source);
  await doc.transform(dedup(), prune(), center({ pivot: "below" }));
  const glb = Buffer.from(await io.writeBinary(doc));
  if (glb.byteLength > MAX_GLB_BYTES) throw new Error(`${id}: ${glb.byteLength} bytes is over the budget`);
  await writeFile(path.join(demoDir, `${id}.glb`), glb);
}

/** A page with one model-viewer on a transparent background. Served locally so the GLB loads like any web page's. */
function serve() {
  const page = `<!doctype html><style>html,body{margin:0;background:transparent}model-viewer{width:${POSTER_PX * 2}px;height:${POSTER_PX * 2}px;--poster-color:transparent}</style>
<script type="module" src="/mv.js"></script><model-viewer id="v" camera-orbit="${ORBIT}" environment-image="neutral" exposure="1" shadow-intensity="0.8" shadow-softness="1" interaction-prompt="none"></model-viewer>`;
  const mv = path.join(root, "node_modules", "@google", "model-viewer", "dist", "model-viewer.min.js");
  const server = createServer((req, res) => {
    const url = new URL(req.url ?? "/", "http://x");
    if (url.pathname === "/") return void res.writeHead(200, { "Content-Type": "text/html" }).end(page);
    if (url.pathname === "/mv.js") return void createReadStream(mv).pipe(res.writeHead(200, { "Content-Type": "text/javascript" }));
    const file = path.join(demoDir, path.basename(url.pathname));
    if (url.pathname.endsWith(".glb") && existsSync(file)) return void createReadStream(file).pipe(res.writeHead(200, { "Content-Type": "model/gltf-binary" }));
    res.writeHead(404).end();
  });
  return new Promise<{ url: string; close: () => void }>((resolve) =>
    server.listen(0, "127.0.0.1", () => resolve({ url: `http://127.0.0.1:${(server.address() as AddressInfo).port}/`, close: () => server.close() })),
  );
}

type Shot = (id: string) => Promise<{ surface: Buffer; mesh: Buffer }>;

async function renderer(url: string): Promise<{ shot: Shot; close: () => Promise<void> }> {
  const browser = await chromium.launch({ channel: "chrome", args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"] });
  const page = await browser.newPage({ viewport: { width: POSTER_PX * 2, height: POSTER_PX * 2 } });
  await page.goto(url);
  await page.waitForFunction(() => Boolean(customElements.get("model-viewer")));
  const grab = (mode: "surface" | "mesh") =>
    page.evaluate(async (m) => {
      type Mat = { wireframe: boolean; map: unknown; normalMap: unknown; needsUpdate: boolean; color?: { set(c: number): void }; emissive?: { set(c: number): void } };
      type Node = { material?: Mat | Mat[]; geometry?: { type?: string } };
      const el = document.getElementById("v") as HTMLElement & { toBlob(o: object): Promise<Blob>; jumpCameraToGoal(): void };
      if (m === "mesh") {
        const symbol = Object.getOwnPropertySymbols(el).find((s) => s.description === "scene")!;
        const scene = (el as unknown as Record<symbol, { traverse(f: (n: Node) => void): void; queueRender(): void }>)[symbol];
        scene.traverse((node) => {
          // The contact shadow is a plane in the same scene: it stays a shadow.
          if (node.geometry?.type === "PlaneGeometry") return;
          for (const mat of [node.material].flat()) {
            if (!mat) continue;
            Object.assign(mat, { wireframe: true, map: null, normalMap: null, needsUpdate: true });
            mat.color?.set(0xb79cff);
            mat.emissive?.set(0x4a35a8);
          }
        });
        scene.queueRender();
      }
      el.jumpCameraToGoal();
      await new Promise((r) => setTimeout(r, 900));
      const blob = await el.toBlob({ mimeType: "image/png", idealAspect: true });
      const bytes = new Uint8Array(await blob.arrayBuffer());
      let out = "";
      for (let i = 0; i < bytes.length; i += 32768) out += String.fromCharCode(...bytes.subarray(i, i + 32768));
      return btoa(out);
    }, mode);
  const toWebp = async (b64: string) => sharp(Buffer.from(b64, "base64")).resize(POSTER_PX, POSTER_PX, { fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 } }).webp({ quality: 82, alphaQuality: 90 }).toBuffer();
  return {
    close: () => browser.close(),
    async shot(id) {
      await page.evaluate(
        (src) =>
          new Promise<void>((resolve, reject) => {
            const el = document.getElementById("v") as HTMLElement & { src: string };
            el.addEventListener("load", () => resolve(), { once: true });
            el.addEventListener("error", () => reject(new Error("load failed")), { once: true });
            el.src = src;
          }),
        `/${id}.glb`,
      );
      return { surface: await toWebp(await grab("surface")), mesh: await toWebp(await grab("mesh")) };
    },
  };
}

async function main() {
  const cache = process.argv[2];
  if (!cache) throw new Error("Usage: build-examples.ts <cache-dir>");
  await mkdir(posterDir, { recursive: true });

  for (const [id, polyId] of Object.entries(SOURCES)) {
    await pack(await fetchSource(polyId, path.resolve(cache)), id);
    console.log(`[ok] packed ${id}`);
  }

  const http = await serve();
  const { shot, close } = await renderer(http.url);
  const data: Record<string, { triangles: number; bytes: number; textureSize: number }> = {};
  try {
    for (const id of [...Object.keys(SOURCES), ...LOCAL]) {
      const { surface, mesh } = await shot(id);
      await writeFile(path.join(posterDir, `${id}.webp`), surface);
      await writeFile(path.join(posterDir, `${id}-mesh.webp`), mesh);
      if (id in SOURCES) {
        const d = await diagnoseGlb(await readFile(path.join(demoDir, `${id}.glb`)));
        data[id] = { triangles: d.triangles, bytes: d.bytes, textureSize: d.maxTextureSize };
      }
      console.log(`[ok] rendered ${id}`);
    }
  } finally {
    await close();
    http.close();
  }
  await writeFile(path.join(root, "src", "content", "examples-data.json"), JSON.stringify(data, null, 2) + "\n");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
